const api = {
  async request(endpoint, options = {}) {
    const config = {
      credentials: 'same-origin',
      headers: {
        'Content-Type': 'application/json',
        ...options.headers
      },
      ...options
    };

    if (config.body && typeof config.body === 'object' && !(config.body instanceof FormData)) {
      config.body = JSON.stringify(config.body);
    }

    const response = await fetch(endpoint, config);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      const error = new Error(data.error || 'Something went wrong');
      error.status = response.status;
      error.data = data;
      throw error;
    }
    return data;
  },

  async signup(email, password) { return this.request('/api/auth/signup', { method: 'POST', body: { email, password } }); },
  async login(email, password) { return this.request('/api/auth/login', { method: 'POST', body: { email, password } }); },
  async logout() { return this.request('/api/auth/logout', { method: 'POST' }); },
